<?php require __DIR__.'/../config/bootstrap.php';admin_required();$p=$pdo->query("SELECT * FROM promotions ORDER BY id DESC LIMIT 1")->fetch();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf($_POST['csrf']??'');$d=[trim($_POST['offer_text']),trim($_POST['title']),trim($_POST['subtitle']),trim($_POST['description']),str_replace('T',' ',trim($_POST['end_date'])),trim($_POST['hero_image']),isset($_POST['is_active'])?1:0];if($p){$q=$pdo->prepare("UPDATE promotions SET offer_text=?,title=?,subtitle=?,description=?,end_date=?,hero_image=?,is_active=? WHERE id=?");$q->execute([...$d,$p['id']]);}else{$q=$pdo->prepare("INSERT INTO promotions(offer_text,title,subtitle,description,end_date,hero_image,is_active) VALUES(?,?,?,?,?,?,?)");$q->execute($d);}$p=$pdo->query("SELECT * FROM promotions ORDER BY id DESC LIMIT 1")->fetch();$msg='Promotion saved.';}$dt=date('Y-m-d\TH:i',strtotime($p['end_date']));?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Promotion</title><link rel="stylesheet" href="admin.css"></head><body><div class="shell"><aside><div class="mark">R+</div><a href="dashboard.php">Dashboard</a><a href="promotion.php">Promotion</a><a href="leads.php">Leads</a><a href="settings.php">Settings</a><a href="logout.php">Logout</a></aside><main><div class="head"><div><small>CMS</small><h1>Promotion</h1></div></div><section class="panel form"><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Offer label<input name="offer_text" value="<?=e($p['offer_text'])?>" required></label><label>Headline<input name="title" value="<?=e($p['title'])?>" required></label><label>Subtitle<input name="subtitle" value="<?=e($p['subtitle'])?>"></label><label>Description<textarea name="description" rows="5"><?=e($p['description'])?></textarea></label><label>End date/time<input type="datetime-local" name="end_date" value="<?=$dt?>" required></label><label>Hero image URL<input name="hero_image" value="<?=e($p['hero_image'])?>"></label><label class="inline"><input type="checkbox" name="is_active" value="1" <?=$p['is_active']?'checked':''?>> Active promotion</label><button>Save promotion</button></form></section></main></div></body></html>
